const CACHE_NAME = 'hiddenyatra-v4';
const STATIC_ASSETS = [
'/',
'/static/css/main.min.css',
'/static/css/components.min.css',
'/static/css/animations.min.css',
'/static/js/app.min.js',
'/static/icon-192.png',
'/static/icon-512.png',
];self.addEventListener('install', (event) => {
event.waitUntil(
caches.open(CACHE_NAME).then((cache) => {
return cache.addAll(STATIC_ASSETS);
})
);
self.skipWaiting();
});self.addEventListener('activate', (event) => {
event.waitUntil(
caches.keys().then((keys) => {
return Promise.all(
keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
);
})
);
self.clients.claim();
});self.addEventListener('fetch', (event) => {
if (event.request.method !== 'GET') return;
const url = new URL(event.request.url);
if (url.pathname.startsWith('/api/') || url.pathname.startsWith('/admin/')) return;event.respondWith(
fetch(event.request)
.then((response) => {
if (response.ok && url.pathname.startsWith('/static/')) {
const responseClone = response.clone();
caches.open(CACHE_NAME).then((cache) => {
cache.put(event.request, responseClone);
});
}
return response;
})
.catch(() => {
return caches.match(event.request);
})
);
});
self.addEventListener('fetch',e=>{'navigate'===e.request.mode&&e.respondWith(fetch(e.request).catch(()=>caches.match('/offline')))});